        rest.unmarkerLawsuit(
            this.tag(),
            pkset,
            {
                scope: this,
                fn: function() {
                    this.getLawsuitGrid().getStore().reload();
                    this.getLawsuitMarkerGrid().getStore().reload();
                    this.getTagGrid().getStore().reload();
                }
            },
            {
                fn: function(message) {
                    Ext.Msg.show({
                        title: 'Marcando o procedimento...',
                        msg: message,
                        icon: Ext.Msg.ERROR,
                        buttons: Ext.Msg.OK
                    });
                }
            },
            {
                fn: function() {
                    mask.hide();
                }
            }
        );
