Ext._define('judicial.statisticMarker.Manage', {
    extend: 'toolkit.widget.TabPanel',

    getStatisticMarkerGrid: function() {
        if(!this._statisticMarkerGrid) {
            this._statisticMarkerGrid = Ext._create('judicial.statisticMarker.Grid', {
                region: 'north',
                height: 300,
                minHeight: 300,
                split: true,
                gridAutoLoad: true
            });

            this._statisticMarkerGrid.getSelectionModel().on({
                scope: this,
                selectionchange: function(sm) {
                    var selection = sm.getSelections();

                    if (selection.length > 0) {
                        this.statisticMarker(selection[0]);
                    } else {
                        this.statisticMarker(null);
                    }
                }
            });
        }

        return this._statisticMarkerGrid;
    },

    statisticMarker: function(value, prevent) {
        prevent = prevent !== undefined ? prevent : false;

        if (value !== undefined) {
            this._statisticMarker = value;

            if (!prevent) {
                this.statisticMarkerObserve();
            }
        }

        return this._statisticMarker;
    },

    statisticMarkerObserve: function() {
        var value = this.statisticMarker();

        if (value) {
            this.getOutCourtLawsuitGrid().enable();
            this.getOutCourtLawsuitGrid().setFilterProperty('statistic_markers', value.get('pk'), 100);
        } else {
            this.getOutCourtLawsuitGrid().disable();
            this.getOutCourtLawsuitGrid().setFilterProperty('statistic_markers', 0, 100, false);
            this.getOutCourtLawsuitGrid().getStore().removeAll();
        }
    },

    getOutCourtLawsuitGrid: function(cfg) {
      if (!this._outCourtLawsuitGrid) {
        this._outCourtLawsuitGrid = Ext._create('judicial.outcourtlawsuit.OutCourtLawsuitAdminGrid', {
            gridAutoLoad: false,
            region: 'center',
            minHeight: 300
        });
      }

      return this._outCourtLawsuitGrid;
    },

    constructor: function(cfg) {
        cfg = core.nullValue(cfg, {});

        Ext.applyIf(
            cfg,
            {
                title: 'Marcadores Estatisticos'
            }
        );

        Ext.apply(
            cfg,
            {
                layout: 'border',
                items: [
                    this.getStatisticMarkerGrid(cfg),
                    this.getOutCourtLawsuitGrid(cfg)
                ]
            }
        );

        judicial.statisticMarker.Manage.superclass.constructor.call(this, cfg);
        this.statisticMarkerObserve();
    }
});


